// ModifyAll updates a field for all records matching current filters
// Returns the number of records modified
func (t *ResourcesSetup) ModifyAll(fieldName string, newValue interface{}) int {
	tableName := fmt.Sprintf("%s$%s", t.company, ResourcesSetupTableName)
	column, ok := t.columnName(fieldName)
	if !ok {
		fmt.Printf("Error: ModifyAll on unknown field %q of Resources_Setup\n", fieldName)
		return 0
	}
	where, args := t.buildWhereClause()

	// Build UPDATE SQL
	updateSQL := fmt.Sprintf(`UPDATE "%s" SET %s = ? WHERE %s`, tableName, column, where)

	// Prepend newValue to args
	allArgs := append([]interface{}{newValue}, args...)

	// Convert placeholders for PostgreSQL
	updateSQL = t.convertPlaceholders(updateSQL, len(allArgs))

	result, err := t.exec().Exec(updateSQL, allArgs...)
	if err != nil {
		fmt.Printf("Error: Failed to modify all Resources_Setup: %v\n", err)
		return 0
	}

	rowsAffected, _ := result.RowsAffected()
	return int(rowsAffected)
}

// DeleteAll deletes all records matching current filters
// Returns the number of records deleted
func (t *ResourcesSetup) DeleteAll() int {
	tableName := fmt.Sprintf("%s$%s", t.company, ResourcesSetupTableName)
	where, args := t.buildWhereClause()

	// Build DELETE SQL
	deleteSQL := fmt.Sprintf(`DELETE FROM "%s" WHERE %s`, tableName, where)

	// Convert placeholders for PostgreSQL
	deleteSQL = t.convertPlaceholders(deleteSQL, len(args))

	result, err := t.exec().Exec(deleteSQL, args...)
	if err != nil {
		fmt.Printf("Error: Failed to delete all Resources_Setup: %v\n", err)
		return 0
	}

	rowsAffected, _ := result.RowsAffected()
	return int(rowsAffected)
}

// CopyFilters copies filters from another record variable (all filter groups)
func (t *ResourcesSetup) CopyFilters(from *ResourcesSetup) {
	t.filters = copyResourcesSetupFilters(from.filters)
	t.filterGroup = from.filterGroup
	t.otherFilters = nil
	for g, filters := range from.otherFilters {
		if t.otherFilters == nil {
			t.otherFilters = map[int]map[string]*resourcesSetupFilterCondition{}
		}
		t.otherFilters[g] = copyResourcesSetupFilters(filters)
	}

	// Also copy order by fields
	if len(from.orderByFields) > 0 {
		t.orderByFields = make([]string, len(from.orderByFields))
		copy(t.orderByFields, from.orderByFields)
	} else {
		t.orderByFields = nil
	}
}

// copyResourcesSetupFilters returns a deep copy of a filter group's filters (nil for none)
func copyResourcesSetupFilters(from map[string]*resourcesSetupFilterCondition) map[string]*resourcesSetupFilterCondition {
	if from == nil {
		return nil
	}
	filters := make(map[string]*resourcesSetupFilterCondition, len(from))
	for key, filter := range from {
		c := *filter
		filters[key] = &c
	}
	return filters
}

// GetFilters returns a string representation of current filters
// Useful for debugging and logging
func (t *ResourcesSetup) GetFilters() string {
	if len(t.filters) == 0 {
		return ""
	}

	var parts []string
	for _, filter := range t.filters {
		if filter.invalidField {
			parts = append(parts, "<invalid field>")
		} else if filter.isExpression {
			parts = append(parts, fmt.Sprintf("%s: %s", filter.fieldName, filter.filterExpr))
		} else if filter.minValue != nil && filter.maxValue != nil {
			parts = append(parts, fmt.Sprintf("%s: %v..%v", filter.fieldName, filter.minValue, filter.maxValue))
		} else if filter.minValue != nil {
			parts = append(parts, fmt.Sprintf("%s: >=%v", filter.fieldName, filter.minValue))
		} else if filter.maxValue != nil {
			parts = append(parts, fmt.Sprintf("%s: <=%v", filter.fieldName, filter.maxValue))
		}
	}

	return strings.Join(parts, ", ")
}

// ========================================
// Field Validation
// ========================================

// ValidateField validates a field and calls its OnValidate trigger
// This is equivalent to the VALIDATE function
// Usage: customer.ValidateField("Payment_terms_code", types.NewCode("30DAYS"))
func (t *ResourcesSetup) ValidateField(fieldName string, value interface{}) error {
	fieldNameLower := strings.ToLower(fieldName)

	switch fieldNameLower {
	case "primary_key":
		// Set field value
		if v, ok := value.(types.Code); ok {
			t.Primary_key = v
		} else if v, ok := value.(string); ok {
			t.Primary_key = types.NewCode(v)
		} else {
			return fmt.Errorf("invalid type for field primary_key")
		}
		// OnValidate trigger of the business logic (OnValidate of the field)
		for _, l := range t.registeredLogic() {
			if trg, ok := l.(ResourcesSetupOnValidate_Primary_key); ok {
				if err := trg.OnValidate_Primary_key(t); err != nil {
					return err
				}
			}
		}
		return nil
	case "resource_nos":
		// Set field value
		if v, ok := value.(types.Code); ok {
			t.Resource_nos = v
		} else if v, ok := value.(string); ok {
			t.Resource_nos = types.NewCode(v)
		} else {
			return fmt.Errorf("invalid type for field resource_nos")
		}
		// TableRelation: the value must exist in the related table (before OnValidate)
		if err := tables.CheckRelation(t, t.db, t.company, t.dbType, "resource_nos"); err != nil {
			return err
		}
		// OnValidate trigger of the business logic (OnValidate of the field)
		for _, l := range t.registeredLogic() {
			if trg, ok := l.(ResourcesSetupOnValidate_Resource_nos); ok {
				if err := trg.OnValidate_Resource_nos(t); err != nil {
					return err
				}
			}
		}
		return nil
	}

	return fmt.Errorf("field '%s' not found", fieldName)
}

